files.tools/rename.ts:
export function rename(name: string) {
  return name.replace(/^feature\//, "feat/");
}

files.tools/stats.ts:
export function stats(lines: string[]) {
  return lines.filter((line) => line.trim() !== "").length;
}

files.tools/cleanup.ts:
export function cleanup(paths: string[]) {
  return paths.filter((path) => !path.endsWith(".tmp"));
}
